/**
 *
 * The useTooltipManager manages the state and functionality of a tooltip manager component.
 *
 * [Live Demo](https://www.primereact.org/tooltip/)
 *
 * @module useTooltipManager
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
/**
 * Defines valid properties in useTooltipManager.
 */
export interface UseTooltipManagerProps {
    /**
     * The delay in milliseconds before opening a tooltip.
     */
    openDelay?: number | undefined;
    /**
     * The delay in milliseconds before closing a tooltip.
     */
    closeDelay?: number | undefined;
    /**
     * The timeout in milliseconds for the instant phase.
     * If another tooltip opens within this timeout after a tooltip closes,
     * the transition will be instant.
     * @default 400
     */
    timeout?: number;
}
/**
 * Defines valid state in useTooltipManager.
 */
export interface UseTooltipManagerState {
    /**
     * Whether the manager is in the instant phase.
     * When true, tooltips should open/close instantly without delay.
     */
    isInstantPhase: boolean;
    /**
     * The ID of the last tooltip that was closed.
     * Used to distinguish same-tooltip re-open vs different-tooltip transition.
     */
    lastClosedTooltipId: string | null;
    /**
     * The ID of the currently open tooltip.
     * Used to detect group transitions (hovering from one tooltip to another).
     */
    currentOpenTooltipId: string | null;
    /**
     * The group-level open delay override.
     */
    openDelay: number | undefined;
    /**
     * The group-level close delay override.
     */
    closeDelay: number | undefined;
}
/**
 * Defines the methods and properties exposed by useTooltipManager.
 */
export interface UseTooltipManagerExposes {
    /**
     * Current state of the tooltip manager.
     */
    state: UseTooltipManagerState;
    /**
     * Notify the manager that a tooltip has opened.
     * @param tooltipId - The ID of the tooltip that opened.
     * @param closeFn - A callback to force-close this tooltip with instant animation.
     */
    notifyOpen: (tooltipId: string, closeFn: () => void) => void;
    /**
     * Notify the manager that a tooltip has closed.
     */
    notifyClose: (tooltipId: string) => void;
    /**
     * Force-close the currently open tooltip with instant animation (data-instant).
     * Used during group transitions to instantly dismiss the previous tooltip.
     */
    closeCurrentTooltip: () => void;
}
/**
 * Instance of useTooltipManager headless.
 */
export type UseTooltipManagerInstance = HeadlessInstance<UseTooltipManagerProps, UseTooltipManagerState, UseTooltipManagerExposes>;
